{
  "name": "reqflow",
  "private": true,
  "type": "module",
  "description": "AI-assisted customer-requirements workbench for BMW product managers (hackathon prototype).",
  "workspaces": [
    "packages/*",
    "apps/*"
  ],
  "engines": {
    "node": ">=22.13"
  },
  "scripts": {
    "dev": "npm run dev -w @reqflow/web",
    "build": "npm run build -w @reqflow/web",
    "typecheck": "npm run typecheck --workspaces --if-present",
    "test": "vitest run",
    "test:watch": "vitest",
    "format": "prettier --write .",
    "format:check": "prettier --check .",
    "check": "npm run typecheck && npm run test && npm run format:check"
  },
  "devDependencies": {
    "@types/node": "^26.6.5",
    "prettier": "^3.9.10",
    "typescript": "~6.0.3",
    "vitest": "^5.0.3"
  }
}

/** Prefixes keep IDs self-describing in logs, the audit trail and exports. */
export const ID_PREFIX = {
  source: "src",
  record: "rec",
  finding: "fnd",
  theme: "thm",
  workflow: "wf",
  run: "run",
  audit: "aud",
  file: "file",
} as const;

export type IdPrefix = (typeof ID_PREFIX)[keyof typeof ID_PREFIX];

export function newId(prefix: IdPrefix): string {
  return `${prefix}_${crypto.randomUUID().replaceAll("-", "").slice(0, 16)}`;
}

/** Requirement IDs are human-readable and stable across versions, e.g. `REQ-5S-EU-007`. */
export const REQUIREMENT_ID_PATTERN = /^REQ-[A-Z0-9]+-[A-Z0-9]+-\d{3,}$/;

const CODE_PATTERN = /^[A-Z0-9]+$/;

/** `seq` is per scope (vehicle × market) and must never be reused, even after a rejection. */
export function formatRequirementId(vehicleCode: string, market: string, seq: number): string {
  if (!CODE_PATTERN.test(vehicleCode)) {
    throw new RangeError(`vehicleCode must be uppercase alphanumeric, got "${vehicleCode}"`);
  }
  if (!CODE_PATTERN.test(market)) {
    throw new RangeError(`market must be uppercase alphanumeric, got "${market}"`);
  }
  if (!Number.isInteger(seq) || seq < 1) {
    throw new RangeError(`Requirement sequence must be a positive integer, got ${seq}`);
  }
  return `REQ-${vehicleCode}-${market}-${String(seq).padStart(3, "0")}`;
}

import { z } from "zod";

/** Vehicle lines and markets named in the briefing. The schema stays open so other lines/markets work too. */
export const KNOWN_VEHICLE_LINES = ["1 Series", "5 Series", "7 Series"] as const;
export const KNOWN_MARKETS = ["EU", "CN", "US"] as const;

/** What a workflow run is about: one derivative in one market, looking `horizonYears` ahead. */
export const ProductScope = z.object({
  vehicleLine: z.string().min(1), // "5 Series"
  derivative: z.string().min(1).optional(), // "Sedan", "Touring", "i5"
  vehicleCode: z.string().regex(/^[A-Z0-9]{1,6}$/), // short code used in requirement IDs, e.g. "5S"
  market: z.string().regex(/^[A-Z0-9]{2,6}$/), // "EU" | "CN" | "US" | …
  horizonYears: z.number().int().min(1).max(10), // briefing: think 3–5 years ahead
});
export type ProductScope = z.infer<typeof ProductScope>;

import { z } from "zod";

export const SourceKind = z.enum([
  // provided by BMW per vehicle
  "customer_feedback",
  "equipment_data",
  "sales_volume",
  "customer_study",
  // external enrichment
  "competitor",
  "review",
  "market_trend",
  "other_web",
]);
export type SourceKind = z.infer<typeof SourceKind>;

export const SourceOrigin = z.enum(["bmw_internal", "web"]);
export type SourceOrigin = z.infer<typeof SourceOrigin>;

/** Trust in the source itself (not in a claim derived from it). Feeds the evidence level. */
export const Reliability = z.enum(["high", "medium", "low"]);
export type Reliability = z.infer<typeof Reliability>;

/** A document, dataset or web page that evidence comes from. */
export const Source = z.object({
  id: z.string().startsWith("src_"),
  kind: SourceKind,
  origin: SourceOrigin,
  title: z.string().min(1),
  uri: z.string().optional(), // URL, or `file_…` id of an upload
  publisher: z.string().optional(),
  publishedAt: z.iso.datetime().optional(),
  retrievedAt: z.iso.datetime(),
  reliability: Reliability,
  market: z.string().optional(),
  vehicleLine: z.string().optional(),
});
export type Source = z.infer<typeof Source>;

/** One atomic input item: a feedback comment, a table row, a paragraph of a web page. */
export const SourceRecord = z.object({
  id: z.string().startsWith("rec_"),
  sourceId: z.string().startsWith("src_"),
  text: z.string(), // human-readable content; for tables a "col: value; …" rendering
  fields: z.record(z.string(), z.unknown()).optional(), // original structured columns
  locator: z.string().optional(), // "row 42", "p. 3", "§2" — lets a PM find it in the original
  market: z.string().optional(),
  language: z.string().optional(), // BCP-47, e.g. "de", "zh"
});
export type SourceRecord = z.infer<typeof SourceRecord>;

/** Points from a finding/requirement to the exact evidence. `excerpt` must be verbatim. */
export const EvidenceRef = z.object({
  sourceId: z.string().startsWith("src_"),
  recordId: z.string().startsWith("rec_").optional(),
  excerpt: z.string().min(1).max(1000),
  locator: z.string().optional(),
});
export type EvidenceRef = z.infer<typeof EvidenceRef>;

import { z } from "zod";
import { RequirementCategory } from "./category";
import { EvidenceRef } from "./source";

/** Signal types the briefing asks us to extract. */
export const FindingKind = z.enum([
  "complaint", // recurring pain point
  "unmet_need", // something customers want but don't get
  "praise", // keep/protect — what customers love
  "competitor_advantage", // a competitor does it better
  "market_trend", // forward-looking signal (3–5 years)
  "usage_pattern", // from equipment take rates / sales volumes
]);
export type FindingKind = z.infer<typeof FindingKind>;

/** A normalized, evidence-linked signal. Every finding must cite at least one source. */
export const Finding = z.object({
  id: z.string().startsWith("fnd_"),
  kind: FindingKind,
  statement: z.string().min(1), // one normalized sentence, e.g. "Rear legroom is too tight for adults."
  category: RequirementCategory,
  evidence: z.array(EvidenceRef).min(1),
  mentions: z.number().int().nonnegative(), // how many records support it (after dedup)
  sentiment: z.number().min(-1).max(1).optional(),
  markets: z.array(z.string()),
  themeId: z.string().startsWith("thm_").optional(),
  confidence: z.number().min(0).max(1), // extractor's confidence that the statement reflects the evidence
  inScope: z.boolean(),
  outOfScopeReason: z.string().optional(), // required when inScope=false
});
export type Finding = z.infer<typeof Finding>;

/** A cluster of duplicate/related findings (BMW process: "classify, cluster, contextualize"). */
export const Theme = z.object({
  id: z.string().startsWith("thm_"),
  label: z.string().min(1),
  summary: z.string(),
  category: RequirementCategory,
  findingIds: z.array(z.string().startsWith("fnd_")).min(1),
});
export type Theme = z.infer<typeof Theme>;

import { z } from "zod";

/** Who or what initiated a change. Every audit event names one. */
export const Actor = z.discriminatedUnion("type", [
  z.object({
    type: z.literal("ai"),
    component: z.string().min(1), // node type, e.g. "requirements.derive"
    model: z.string().min(1), // exact model id, or "deterministic" for rule-based steps
  }),
  z.object({
    type: z.literal("human"),
    userId: z.string().min(1),
    name: z.string().min(1),
    role: z.string().optional(), // "Product Manager"
  }),
  z.object({
    type: z.literal("system"),
    component: z.string().min(1), // "engine", "api", …
  }),
]);
export type Actor = z.infer<typeof Actor>;

export const AuditAction = z.enum([
  "source.ingested",
  "finding.extracted",
  "finding.merged",
  "finding.excluded", // scope filter dropped it (rationale = reason)
  "requirement.proposed",
  "requirement.edited",
  "requirement.scored",
  "requirement.prioritized",
  "requirement.evidence_linked",
  "requirement.evidence_unlinked",
  "requirement.merged",
  "requirement.status_changed",
  "requirement.challenged",
  "requirement.challenge_answered",
  "requirement.viewed", // access event
  "workflow.saved",
  "run.started",
  "run.paused",
  "run.resumed",
  "run.completed",
  "run.failed",
  "settings.changed",
  "export.created",
]);
export type AuditAction = z.infer<typeof AuditAction>;

export const AuditEntityType = z.enum([
  "source",
  "finding",
  "requirement",
  "workflow",
  "run",
  "settings",
  "export",
]);
export type AuditEntityType = z.infer<typeof AuditEntityType>;

export const FieldChange = z.object({
  path: z.string().min(1), // dot path into the entity, e.g. "score.total", "status"
  before: z.unknown(),
  after: z.unknown(),
});
export type FieldChange = z.infer<typeof FieldChange>;

/**
 * Append-only record. Never updated or deleted.
 * Human decisions MUST carry a `rationale` (enforced by the API, see RequirementDecision).
 */
export const AuditEvent = z.object({
  id: z.string().startsWith("aud_"),
  at: z.iso.datetime(),
  actor: Actor,
  action: AuditAction,
  entityType: AuditEntityType,
  entityId: z.string().min(1),
  changes: z.array(FieldChange),
  rationale: z.string().optional(),
  runId: z.string().startsWith("run_").optional(),
  nodeId: z.string().optional(),
});
export type AuditEvent = z.infer<typeof AuditEvent>;

/** What callers pass to `AuditLogger.record`; the logger assigns `id` and `at`. */
export type AuditEventInput = Omit<AuditEvent, "id" | "at" | "changes"> & {
  changes?: FieldChange[];
};

import { z } from "zod";

/**
 * Explainable prioritization: every factor is 0–5 where HIGHER always means "more worth doing".
 * total = 100 × Σ(weight × value) / (5 × Σ weight)   →   0–100
 * Weights and priority thresholds live in Settings.scoring and are recorded with each score.
 */
export const ScoreFactor = z.enum([
  "customer_impact", // how strongly and how many customers are affected
  "evidence_strength", // number, independence and reliability of supporting sources
  "competitive_gap", // competitors offer it / do it better
  "trend_momentum", // expected relevance when the successor launches (3–5 years)
  "brand_fit", // fit with BMW brand promise (premium, driving pleasure, …)
  "ease", // inverse of rough effort/cost — the only business factor allowed by the briefing
]);
export type ScoreFactor = z.infer<typeof ScoreFactor>;

export const SCORE_FACTOR_LABELS: Record<ScoreFactor, string> = {
  customer_impact: "Customer impact",
  evidence_strength: "Evidence strength",
  competitive_gap: "Competitive gap",
  trend_momentum: "Trend momentum",
  brand_fit: "Brand fit",
  ease: "Ease of delivery (inverse effort)",
};

/** MoSCoW priority bands. */
export const Priority = z.enum(["must", "should", "could", "wont"]);
export type Priority = z.infer<typeof Priority>;

export const ScoreWeights = z.record(ScoreFactor, z.number().min(0).max(10));
export type ScoreWeights = z.infer<typeof ScoreWeights>;

/** Minimum total score for each band; below `could` → "wont". */
export const PriorityThresholds = z
  .object({
    must: z.number().min(0).max(100),
    should: z.number().min(0).max(100),
    could: z.number().min(0).max(100),
  })
  .refine((t) => t.must > t.should && t.should > t.could, {
    message: "Thresholds must satisfy must > should > could",
  });
export type PriorityThresholds = z.infer<typeof PriorityThresholds>;

export const FactorScore = z.object({
  value: z.number().min(0).max(5),
  weight: z.number().min(0).max(10), // weight at scoring time (snapshot of Settings)
  note: z.string().min(1), // one-line justification, shown to the PM
});
export type FactorScore = z.infer<typeof FactorScore>;

export const ScoreBreakdown = z.object({
  factors: z.record(ScoreFactor, FactorScore),
  total: z.number().min(0).max(100),
  suggestedPriority: Priority, // what the score says; Requirement.priority may be overridden by the PM
  method: z.string().min(1), // versioned, e.g. "weighted-sum@1"
  scoredAt: z.iso.datetime(),
});
export type ScoreBreakdown = z.infer<typeof ScoreBreakdown>;

import { z } from "zod";
import { Actor } from "./audit";
import { RequirementCategory } from "./category";
import { REQUIREMENT_ID_PATTERN } from "./ids";
import { ProductScope } from "./scope";
import { Priority, ScoreBreakdown } from "./scoring";

/**
 * How well a requirement is backed — makes "evidence vs. assumption" explicit (briefing).
 *  A strong     – several independent sources incl. quantitative BMW data, consistent
 *  B moderate   – several sources, mostly qualitative, or minor conflicts
 *  C weak       – single source / anecdotal
 *  D assumption – forward-looking, rests mainly on trends or expert judgement
 */
export const EvidenceLevel = z.enum(["A", "B", "C", "D"]);
export type EvidenceLevel = z.infer<typeof EvidenceLevel>;

/**
 * Lifecycle. AI may only ever set `proposed` (and `in_review` after answering a challenge).
 * `approved`, `rejected`, `deferred`, `challenged` are set by a human via RequirementDecision.
 */
export const DecisionStatus = z.enum([
  "proposed",
  "in_review",
  "challenged",
  "approved",
  "rejected",
  "deferred",
]);
export type DecisionStatus = z.infer<typeof DecisionStatus>;

/** Kano classification — helps PMs see basic expectations vs. delighters. */
export const KanoClass = z.enum(["basic", "performance", "delighter", "indifferent"]);
export type KanoClass = z.infer<typeof KanoClass>;

/** BMW process step "Specification and quantification": measurable, customer-perceivable target. */
export const MetricTarget = z.object({
  metric: z.string().min(1), // "Real-world highway range"
  target: z.string().min(1), // "≥ 550 km at 130 km/h, 20 °C"
  acceptance: z.string().min(1), // how a customer / test would confirm it
});
export type MetricTarget = z.infer<typeof MetricTarget>;

export const Requirement = z.object({
  id: z.string().regex(REQUIREMENT_ID_PATTERN), // stable across versions
  version: z.number().int().positive(), // +1 on every content change
  title: z.string().min(1).max(120),
  description: z.string().min(1), // clear, actionable, customer-facing; no engineering specs
  category: RequirementCategory,
  scope: ProductScope,
  targets: z.array(MetricTarget),
  findingIds: z.array(z.string().startsWith("fnd_")).min(1), // traceability: requirement → findings
  sourceIds: z.array(z.string().startsWith("src_")), // denormalized from findings for display/export
  conflictingFindingIds: z.array(z.string().startsWith("fnd_")), // evidence that argues against it
  score: ScoreBreakdown.optional(), // absent until prioritization.score ran
  priority: Priority.optional(), // current priority (suggested or PM override)
  priorityRationale: z.string().optional(),
  evidenceLevel: EvidenceLevel,
  kano: KanoClass.optional(),
  assumptions: z.array(z.string()), // forward-looking assumptions it relies on
  uncertainties: z.array(z.string()), // what could make it wrong
  status: DecisionStatus,
  createdBy: Actor,
  createdAt: z.iso.datetime(),
  updatedAt: z.iso.datetime(),
  runId: z.string().startsWith("run_").optional(),
});
export type Requirement = z.infer<typeof Requirement>;

import { z } from "zod";
import { Finding, Theme } from "./finding";
import { Requirement } from "./requirement";
import { Source, SourceRecord } from "./source";

/**
 * The single envelope that flows along every workflow edge (n8n-style: one input, one output).
 * A node reads the keys it `consumes` and returns the envelope with the keys it `produces` updated.
 */
export const DATA_KEYS = ["sources", "records", "findings", "themes", "requirements"] as const;
export const DataKey = z.enum(DATA_KEYS);
export type DataKey = z.infer<typeof DataKey>;

export const PipelineData = z.object({
  sources: z.array(Source),
  records: z.array(SourceRecord),
  findings: z.array(Finding),
  themes: z.array(Theme),
  requirements: z.array(Requirement),
});
export type PipelineData = z.infer<typeof PipelineData>;

export function emptyPipelineData(): PipelineData {
  return { sources: [], records: [], findings: [], themes: [], requirements: [] };
}

function mergeById<T extends { id: string }>(lists: T[][]): T[] {
  const byId = new Map<string, T>();
  for (const list of lists) for (const item of list) byId.set(item.id, item);
  return [...byId.values()];
}

/**
 * How the engine combines several incoming edges into one node input:
 * concatenate per key and de-duplicate by `id`; a later input wins (order = edge order),
 * first-seen position is kept so output order stays stable.
 */
export function mergePipelineData(...parts: PipelineData[]): PipelineData {
  return {
    sources: mergeById(parts.map((p) => p.sources)),
    records: mergeById(parts.map((p) => p.records)),
    findings: mergeById(parts.map((p) => p.findings)),
    themes: mergeById(parts.map((p) => p.themes)),
    requirements: mergeById(parts.map((p) => p.requirements)),
  };
}

export function countPipelineData(data: PipelineData): Record<DataKey, number> {
  return {
    sources: data.sources.length,
    records: data.records.length,
    findings: data.findings.length,
    themes: data.themes.length,
    requirements: data.requirements.length,
  };
}

import { z } from "zod";
import { Actor } from "./audit";
import { DataKey } from "./pipeline";
import { ProductScope } from "./scope";

/** Palette groups in the editor; mirror the BMW process columns. */
export const NodeCategory = z.enum([
  "source", // situation analysis: BMW data + web
  "analysis", // structure & context: extract, filter, cluster
  "requirements", // requirements definition: derive, specify targets
  "prioritization",
  "review", // human-in-the-loop gates
  "output", // documentation / publish / export
]);
export type NodeCategory = z.infer<typeof NodeCategory>;

export const WorkflowNode = z.object({
  id: z.string().min(1), // unique within the workflow, e.g. "extract-1"
  type: z.string().regex(/^[a-z]+\.[a-z_]+$/), // registry key, e.g. "analysis.extract_signals"
  label: z.string().optional(),
  position: z.object({ x: z.number(), y: z.number() }),
  config: z.record(z.string(), z.unknown()), // validated against the node's configSchema at run time
});
export type WorkflowNode = z.infer<typeof WorkflowNode>;

/** Nodes have exactly one input and one output port, so an edge is just source → target. */
export const WorkflowEdge = z.object({
  id: z.string().min(1),
  source: z.string().min(1),
  target: z.string().min(1),
});
export type WorkflowEdge = z.infer<typeof WorkflowEdge>;

export const WorkflowGraph = z.object({
  nodes: z.array(WorkflowNode),
  edges: z.array(WorkflowEdge),
});
export type WorkflowGraph = z.infer<typeof WorkflowGraph>;

export const Workflow = WorkflowGraph.extend({
  id: z.string().startsWith("wf_"),
  name: z.string().min(1),
  description: z.string().optional(),
  scope: ProductScope,
  version: z.number().int().positive(), // +1 on every save
  createdAt: z.iso.datetime(),
  updatedAt: z.iso.datetime(),
});
export type Workflow = z.infer<typeof Workflow>;

export const RunStatus = z.enum([
  "queued",
  "running",
  "waiting_for_review", // paused at a review.* node until the PM resumes
  "completed",
  "failed",
  "cancelled",
]);
export type RunStatus = z.infer<typeof RunStatus>;

export const NodeRunStatus = z.enum([
  "pending",
  "running",
  "succeeded",
  "failed",
  "skipped", // an upstream node failed
  "waiting_for_review",
]);
export type NodeRunStatus = z.infer<typeof NodeRunStatus>;

export const NodeRunLog = z.object({ at: z.iso.datetime(), message: z.string() });
export type NodeRunLog = z.infer<typeof NodeRunLog>;

/** Status shown on each canvas node. Full node output is stored separately (see ARCHITECTURE.md). */
export const NodeRun = z.object({
  nodeId: z.string().min(1),
  status: NodeRunStatus,
  startedAt: z.iso.datetime().optional(),
  finishedAt: z.iso.datetime().optional(),
  progress: z.number().min(0).max(1).optional(),
  counts: z.partialRecord(DataKey, z.number().int().nonnegative()), // output size per data key
  logs: z.array(NodeRunLog),
  error: z.string().optional(),
});
export type NodeRun = z.infer<typeof NodeRun>;

export const WorkflowRun = z.object({
  id: z.string().startsWith("run_"),
  workflowId: z.string().startsWith("wf_"),
  workflowVersion: z.number().int().positive(),
  graph: WorkflowGraph, // snapshot, so a run stays reproducible after the workflow is edited
  scope: ProductScope,
  status: RunStatus,
  startedBy: Actor,
  startedAt: z.iso.datetime(),
  finishedAt: z.iso.datetime().optional(),
  nodeRuns: z.array(NodeRun),
  error: z.string().optional(),
});
export type WorkflowRun = z.infer<typeof WorkflowRun>;

import { z } from "zod";
import { ProductScope } from "./scope";
import { PriorityThresholds, ScoreWeights } from "./scoring";

/** "mock" returns canned, schema-valid output so the app runs offline and in tests. */
export const LlmProvider = z.enum(["anthropic", "mock"]);
export type LlmProvider = z.infer<typeof LlmProvider>;

export const ResearchProvider = z.enum(["anthropic_web_search", "tavily", "off"]);
export type ResearchProvider = z.infer<typeof ResearchProvider>;

/**
 * Everything the Settings page edits. API keys are NOT settings — they live in .env.local
 * and the server only reports whether one is configured.
 */
export const Settings = z.object({
  llm: z.object({
    provider: LlmProvider,
    model: z.string().min(1), // quality tier: clustering, derivation, challenge answers
    fastModel: z.string().min(1), // bulk tier: per-record signal extraction
    temperature: z.number().min(0).max(1),
  }),
  research: z.object({
    provider: ResearchProvider,
    maxResultsPerQuery: z.number().int().min(1).max(50),
    allowedDomains: z.array(z.string()), // empty = any
    blockedDomains: z.array(z.string()),
  }),
  scoring: z.object({
    weights: ScoreWeights,
    thresholds: PriorityThresholds,
  }),
  review: z.object({
    // The prototype has no login: this identity is the human actor in the audit trail.
    reviewer: z.object({
      userId: z.string().min(1),
      name: z.string().min(1),
      role: z.string().min(1),
    }),
  }),
  defaultScope: ProductScope,
});
export type Settings = z.infer<typeof Settings>;

export const DEFAULT_SETTINGS: Settings = {
  llm: {
    provider: "mock",
    model: "claude-opus-5-5",
    fastModel: "claude-haiku-5-5",
    temperature: 0.2,
  },
  research: {
    provider: "off",
    maxResultsPerQuery: 8,
    allowedDomains: [],
    blockedDomains: [],
  },
  scoring: {
    weights: {
      customer_impact: 3,
      evidence_strength: 2,
      competitive_gap: 2,
      trend_momentum: 2,
      brand_fit: 1,
      ease: 1,
    },
    thresholds: { must: 70, should: 50, could: 30 },
  },
  review: {
    reviewer: { userId: "pm-demo", name: "Demo PM", role: "Product Manager" },
  },
  defaultScope: {
    vehicleLine: "5 Series",
    derivative: "Sedan",
    vehicleCode: "5S",
    market: "EU",
    horizonYears: 5,
  },
};

import type { z } from "zod";
import type { AuditEvent, AuditEventInput } from "./audit";

/**
 * Service interfaces handed to nodes via NodeContext. Implementations live elsewhere
 * (llm → @reqflow/llm, audit/files → @reqflow/db, web search → nodes/research) and are
 * wired together server-side in apps/web/src/server. Nodes never read env vars or the DB directly.
 */

export type ModelTier = "default" | "fast";

export interface LlmObjectRequest<T> {
  system?: string;
  prompt: string;
  schema: z.ZodType<T>;
  tier?: ModelTier; // default: "default"
  signal?: AbortSignal;
}

export interface LlmTextRequest {
  system?: string;
  prompt: string;
  tier?: ModelTier;
  signal?: AbortSignal;
}

export interface LlmClient {
  /** Structured output. MUST validate against `schema` and throw on invalid output — never return partial data. */
  generateObject<T>(req: LlmObjectRequest<T>): Promise<{ object: T; model: string }>;
  generateText(req: LlmTextRequest): Promise<{ text: string; model: string }>;
}

export interface AuditLogger {
  /** Append-only. Assigns id + timestamp and persists before resolving. */
  record(event: AuditEventInput): Promise<AuditEvent>;
}

export interface StoredFile {
  id: string; // "file_…"
  name: string;
  mimeType: string;
  bytes: Uint8Array;
}

export interface FileStore {
  /** Throws if the file does not exist. */
  get(fileId: string): Promise<StoredFile>;
}

export interface WebSearchResult {
  url: string;
  title: string;
  snippet: string;
  publishedAt?: string; // ISO date if known
}

export interface WebSearch {
  search(
    query: string,
    opts?: { maxResults?: number; signal?: AbortSignal },
  ): Promise<WebSearchResult[]>;
}

import { z } from "zod";
import { DecisionStatus, Requirement } from "./requirement";
import { Priority } from "./scoring";

/** Request/response shapes shared by the UI and the route handlers (endpoint list: docs/ARCHITECTURE.md). */

export const DecisionKind = z.enum(["approve", "reject", "defer", "challenge", "reopen"]);
export type DecisionKind = z.infer<typeof DecisionKind>;

export const DECISION_TO_STATUS: Record<DecisionKind, DecisionStatus> = {
  approve: "approved",
  reject: "rejected",
  defer: "deferred",
  challenge: "challenged", // AI answers, then the requirement returns to "in_review"
  reopen: "in_review",
};

/** POST /api/requirements/:id/decision — every human decision needs a rationale. */
export const RequirementDecision = z.object({
  decision: DecisionKind,
  rationale: z.string().trim().min(3),
  priority: Priority.optional(), // optional PM override when approving
});
export type RequirementDecision = z.infer<typeof RequirementDecision>;

/** PATCH /api/requirements/:id — PM edits content; bumps version, audited field by field. */
export const RequirementEdit = Requirement.pick({
  title: true,
  description: true,
  category: true,
  targets: true,
  priority: true,
  priorityRationale: true,
  assumptions: true,
  uncertainties: true,
  findingIds: true,
  conflictingFindingIds: true,
})
  .partial()
  .extend({ rationale: z.string().trim().min(3) })
  .refine((edit) => Object.keys(edit).some((k) => k !== "rationale"), {
    message: "An edit must change at least one field",
  });
export type RequirementEdit = z.infer<typeof RequirementEdit>;

/** Uniform error body for every non-2xx API response. */
export const ApiError = z.object({
  error: z.object({
    code: z.string(),
    message: z.string(),
    details: z.unknown().optional(),
  }),
});
export type ApiError = z.infer<typeof ApiError>;

// @reqflow/core — the shared contract. Changes here affect every workstream: see AGENTS.md.
export * from "./api";
export * from "./audit";
export * from "./category";
export * from "./finding";
export * from "./ids";
export * from "./pipeline";
export * from "./requirement";
export * from "./scope";
export * from "./scoring";
export * from "./services";
export * from "./settings";
export * from "./source";
export * from "./workflow";

import type {
  AuditLogger,
  DataKey,
  FileStore,
  LlmClient,
  NodeCategory,
  PipelineData,
  ProductScope,
  Settings,
  WebSearch,
} from "@reqflow/core";
import type { z } from "zod";

/** Everything a node may touch while running. Nodes must not import DB/env/server code. */
export interface NodeContext {
  runId: string;
  nodeId: string;
  scope: ProductScope;
  settings: Settings; // snapshot taken when the run started
  llm: LlmClient;
  audit: AuditLogger; // record what the node created/changed, with actor { type: "ai", component: <node type> }
  files: FileStore;
  web: WebSearch | null; // null when Settings.research.provider === "off"
  log(message: string): void; // shown in the run panel of the editor
  progress(fraction: number, message?: string): void; // 0–1
  signal: AbortSignal; // run cancelled → stop promptly
  resumed: boolean; // true when a review node is re-entered after the PM resumed the run
}

export type NodeResult =
  | { status: "ok"; data: PipelineData }
  /** Only review.* nodes pause. The engine marks the run `waiting_for_review` and re-invokes the node on resume. */
  | { status: "paused"; message: string };

export interface NodeDefinition<C extends z.ZodType = z.ZodType> {
  type: string; // unique, stable registry key: "<category>.<name>", e.g. "analysis.extract_signals"
  label: string; // palette / canvas title
  description: string; // one or two sentences for the palette tooltip
  category: NodeCategory;
  consumes: DataKey[]; // editor warns if no upstream node produces these
  produces: DataKey[];
  configSchema: C; // drives the config form (served as JSON Schema by GET /api/nodes)
  /** Must be deterministic given (input, config, LLM output) and must throw on bad input — no silent skips. */
  run(input: PipelineData, config: z.infer<C>, ctx: NodeContext): Promise<NodeResult>;
}

/** Identity helper that keeps `config` typed from `configSchema`. */
export function defineNode<C extends z.ZodType>(def: NodeDefinition<C>): NodeDefinition<C> {
  return def;
}

import type { DataKey, NodeCategory } from "@reqflow/core";
import { z } from "zod";
import type { NodeDefinition } from "./node";

/** What GET /api/nodes returns for the editor palette and config forms. */
export interface NodeCatalogEntry {
  type: string;
  label: string;
  description: string;
  category: NodeCategory;
  consumes: DataKey[];
  produces: DataKey[];
  configJsonSchema: unknown; // JSON Schema generated from configSchema
}

export class NodeRegistry {
  private readonly defs = new Map<string, NodeDefinition>();

  constructor(defs: readonly NodeDefinition[] = []) {
    for (const def of defs) this.register(def);
  }

  register(def: NodeDefinition): void {
    if (this.defs.has(def.type)) {
      throw new Error(`Node type "${def.type}" is already registered`);
    }
    if (!/^[a-z]+\.[a-z_]+$/.test(def.type)) {
      throw new Error(`Node type "${def.type}" must look like "<category>.<snake_name>"`);
    }
    this.defs.set(def.type, def);
  }

  get(type: string): NodeDefinition {
    const def = this.defs.get(type);
    if (!def) throw new Error(`Unknown node type "${type}"`);
    return def;
  }

  has(type: string): boolean {
    return this.defs.has(type);
  }

  list(): NodeDefinition[] {
    return [...this.defs.values()];
  }

  catalog(): NodeCatalogEntry[] {
    return this.list().map((def) => ({
      type: def.type,
      label: def.label,
      description: def.description,
      category: def.category,
      consumes: def.consumes,
      produces: def.produces,
      configJsonSchema: z.toJSONSchema(def.configSchema, { unrepresentable: "any" }),
    }));
  }
}

import { emptyPipelineData } from "@reqflow/core";
import { describe, expect, it } from "vitest";
import { z } from "zod";
import { defineNode } from "./node";
import { NodeRegistry } from "./registry";

const passThrough = defineNode({
  type: "analysis.pass_through",
  label: "Pass through",
  description: "Test node.",
  category: "analysis",
  consumes: [],
  produces: [],
  configSchema: z.object({ note: z.string().default("") }),
  run: async (input) => ({ status: "ok", data: input }),
});

describe("NodeRegistry", () => {
  it("registers, resolves and catalogs nodes with a JSON Schema config", async () => {
    const registry = new NodeRegistry([passThrough]);
    const def = registry.get("analysis.pass_through");
    await expect(def.run(emptyPipelineData(), {}, {} as never)).resolves.toMatchObject({
      status: "ok",
    });
    const [entry] = registry.catalog();
    expect(entry?.configJsonSchema).toMatchObject({ type: "object" });
  });

  it("rejects duplicate and malformed node types", () => {
    const registry = new NodeRegistry([passThrough]);
    expect(() => registry.register(passThrough)).toThrow(/already registered/);
    expect(() => registry.register({ ...passThrough, type: "BadType" })).toThrow(/must look like/);
    expect(() => registry.get("nope.missing")).toThrow(/Unknown node type/);
  });
});

