import type { ApiError } from "@reqflow/core";
import type { IpcResult, ReqflowHandlers } from "@reqflow/core/ipc";
import { ZodError } from "zod";

/** Throw this from a handler to send a specific error code to the UI. */
export class ReqflowError extends Error {
  constructor(
    readonly code: string,
    message: string,
    readonly details?: unknown,
  ) {
    super(message);
    this.name = "ReqflowError";
  }
}

export function toIpcError(err: unknown): ApiError["error"] {
  if (err instanceof ReqflowError) {
    return { code: err.code, message: err.message, details: err.details };
  }
  if (err instanceof ZodError) {
    return { code: "invalid_input", message: "Input failed validation", details: err.issues };
  }
  if (err instanceof Error) return { code: "internal", message: err.message };
  return { code: "internal", message: String(err) };
}

/** Pure (Electron-free) so it can be unit-tested: route one IPC call to its handler. */
export async function dispatch(
  handlers: ReqflowHandlers,
  namespace: string,
  method: string,
  args: unknown[],
): Promise<IpcResult<unknown>> {
  const ns = (handlers as unknown as Record<string, Record<string, unknown> | undefined>)[namespace];
  const fn = ns?.[method];
  if (typeof fn !== "function") {
    return {
      ok: false,
      error: { code: "unknown_method", message: `No handler for ${namespace}.${method}` },
    };
  }
  try {
    return { ok: true, value: await fn.apply(ns, args) };
  } catch (err) {
    const error = toIpcError(err);
    if (error.code === "internal") console.error(`[ipc] ${namespace}.${method} failed:`, err);
    return { ok: false, error };
  }
}

import type { AppInfo, ReqflowHandlers } from "@reqflow/core/ipc";
import { BMW_DEFAULT_TEMPLATE, createNodeRegistry } from "@reqflow/nodes";
import { ReqflowError } from "./dispatch";

// Owner: WS1 (docs/WORKSTREAMS.md). Every method the UI can call is listed here; the ones not built
// yet fail loudly with code "not_implemented" so the UI can show a clear message instead of hanging.
// Validate every argument with the Zod schemas from @reqflow/core — the renderer is untrusted input.

function notBuilt(method: string, owner = "WS1") {
  return async (): Promise<never> => {
    throw new ReqflowError(
      "not_implemented",
      `${method} is not built yet — owner ${owner}, see docs/WORKSTREAMS.md`,
    );
  };
}

export interface HandlerDeps {
  appInfo: () => AppInfo;
}

export function createHandlers(deps: HandlerDeps): ReqflowHandlers {
  const registry = createNodeRegistry();
  return {
    app: { info: async () => deps.appInfo() },
    nodes: { catalog: async () => registry.catalog() },
    templates: { list: async () => [BMW_DEFAULT_TEMPLATE] },
    workflows: {
      list: notBuilt("workflows.list"),
      get: notBuilt("workflows.get"),
      save: notBuilt("workflows.save"),
      remove: notBuilt("workflows.remove"),
    },
    files: { import: notBuilt("files.import") },
    runs: {
      start: notBuilt("runs.start"),
      get: notBuilt("runs.get"),
      list: notBuilt("runs.list"),
      nodeOutput: notBuilt("runs.nodeOutput"),
      resume: notBuilt("runs.resume"),
      cancel: notBuilt("runs.cancel"),
    },
    requirements: {
      list: notBuilt("requirements.list"),
      get: notBuilt("requirements.get"),
      edit: notBuilt("requirements.edit"),
      decide: notBuilt("requirements.decide"),
    },
    audit: { list: notBuilt("audit.list") },
    settings: {
      get: notBuilt("settings.get"),
      save: notBuilt("settings.save"),
      secrets: notBuilt("settings.secrets"),
      setSecret: notBuilt("settings.setSecret"),
    },
    exports: { requirements: notBuilt("exports.requirements") },
  };
}

import { IPC_INVOKE_METHODS, ipcChannel, type ReqflowHandlers } from "@reqflow/core/ipc";
import { ipcMain, type IpcMainInvokeEvent } from "electron";
import { dispatch } from "./dispatch";

/** Registers one `ipcMain.handle` per contract method. Calls from untrusted frames are refused. */
export function registerIpc(
  handlers: ReqflowHandlers,
  isTrustedSender: (event: IpcMainInvokeEvent) => boolean,
): void {
  for (const [namespace, methods] of Object.entries(IPC_INVOKE_METHODS)) {
    for (const method of methods) {
      ipcMain.handle(ipcChannel(namespace, method), (event, ...args: unknown[]) => {
        if (!isTrustedSender(event)) {
          return {
            ok: false,
            error: { code: "forbidden", message: "IPC call from an untrusted frame" },
          };
        }
        return dispatch(handlers, namespace, method, args);
      });
    }
  }
}

import { existsSync } from "node:fs";
import { join, resolve } from "node:path";
import { app } from "electron";

/**
 * Where the database and imported datasets live. Per-user and per-OS by default:
 *   macOS   ~/Library/Application Support/ReqFlow/data
 *   Windows %APPDATA%\ReqFlow\data
 *   Linux   ~/.config/ReqFlow/data
 * REQFLOW_DATA_DIR overrides it (tests, smoke runs, demos with a prepared dataset).
 */
export function dataDir(override?: string | null): string {
  const custom = override ?? process.env.REQFLOW_DATA_DIR;
  return custom ? resolve(custom) : join(app.getPath("userData"), "data");
}

export const dbFile = (dir: string): string => join(dir, "reqflow.db");
export const uploadsDir = (dir: string): string => join(dir, "uploads");

/** Dev only: load apps/desktop/.env (API keys for local testing). Packaged apps use the OS keychain. */
export function loadDevEnv(): void {
  if (app.isPackaged) return;
  const file = join(app.getAppPath(), ".env");
  if (existsSync(file)) process.loadEnvFile(file);
}

import { mkdirSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import type { BrowserWindow } from "electron";

/**
 * `npm run smoke` (= `electron . --smoke=out/smoke`): opens every screen, screenshots it,
 * calls the IPC bridge end to end, and exits non-zero on any renderer error. Used by CI on all OSes
 * and by agents to verify UI work without clicking through the app.
 */
export const SMOKE_ROUTES = [
  "/workflow",
  "/requirements",
  "/requirements/REQ-5S-EU-001",
  "/audit",
  "/settings",
] as const;

export function parseSmokeArg(argv: readonly string[]): string | null {
  const arg = argv.find((a) => a.startsWith("--smoke="));
  return arg ? resolve(arg.slice("--smoke=".length)) : null;
}

const delay = (ms: number) => new Promise((r) => setTimeout(r, ms));
const slug = (route: string) => route.replace(/^\//, "").replace(/[^a-zA-Z0-9]+/g, "-") || "root";

export async function runSmoke(win: BrowserWindow, outDir: string): Promise<number> {
  mkdirSync(outDir, { recursive: true });
  const errors: string[] = [];
  const wc = win.webContents;
  wc.on("console-message", (event) => {
    if (event.level === "error") errors.push(`console: ${event.message}`);
  });
  wc.on("render-process-gone", (_e, details) => errors.push(`renderer gone: ${details.reason}`));

  if (wc.isLoading()) await new Promise<void>((r) => wc.once("did-finish-load", () => r()));

  // IPC bridge, end to end: one built method must succeed, an unbuilt one must fail loudly.
  const info = await wc.executeJavaScript(`window.reqflowBridge.invoke("reqflow:app.info")`);
  if (!info?.ok) errors.push(`app.info failed: ${JSON.stringify(info)}`);
  const unbuilt = await wc.executeJavaScript(`window.reqflowBridge.invoke("reqflow:audit.list")`);
  if (unbuilt?.ok !== false || !unbuilt.error?.code) {
    errors.push(`audit.list should return a structured error, got ${JSON.stringify(unbuilt)}`);
  }
  const blocked = await wc.executeJavaScript(
    `window.reqflowBridge.invoke("not-a-channel").then(() => "allowed", () => "blocked")`,
  );
  if (blocked !== "blocked") errors.push("preload allowed an unknown IPC channel");

  const screens: { route: string; heading: string; file: string }[] = [];
  for (const route of SMOKE_ROUTES) {
    await wc.executeJavaScript(`location.hash = ${JSON.stringify(`#${route}`)}`);
    await delay(500);
    const heading: string = await wc.executeJavaScript(
      `document.querySelector("h1")?.textContent ?? ""`,
    );
    if (!heading) errors.push(`${route}: no <h1> rendered`);
    const file = join(outDir, `${slug(route)}.png`);
    writeFileSync(file, (await wc.capturePage()).toPNG());
    screens.push({ route, heading, file });
  }

  const report = { ok: errors.length === 0, platform: process.platform, errors, screens };
  writeFileSync(join(outDir, "report.json"), JSON.stringify(report, null, 2));
  console.log(
    `[smoke] ${report.ok ? "PASS" : "FAIL"} on ${process.platform}: ${screens.length} screens → ${outDir}`,
  );
  for (const e of errors) console.error(`[smoke] ${e}`);
  return report.ok ? 0 : 1;
}

import { join } from "node:path";
import { app, BrowserWindow, shell, type IpcMainInvokeEvent } from "electron";
import { createHandlers } from "./handlers";
import { registerIpc } from "./ipc";
import { dataDir, loadDevEnv } from "./paths";
import { parseSmokeArg, runSmoke } from "./smoke";

const smokeDir = parseSmokeArg(process.argv);

// One instance per user: two processes writing the same SQLite file would corrupt the audit trail.
if (!smokeDir && !app.requestSingleInstanceLock()) app.quit();

function createWindow(): BrowserWindow {
  const win = new BrowserWindow({
    width: 1440,
    height: 900,
    minWidth: 1024,
    minHeight: 640,
    title: "ReqFlow",
    show: false,
    autoHideMenuBar: true,
    webPreferences: {
      preload: join(__dirname, "../preload/index.js"),
      contextIsolation: true,
      sandbox: true,
      nodeIntegration: false,
    },
  });
  win.once("ready-to-show", () => (smokeDir ? win.showInactive() : win.show()));

  // The window never navigates away from the app; http(s) links open in the user's browser.
  win.webContents.setWindowOpenHandler(({ url }) => {
    if (/^https?:\/\//.test(url)) void shell.openExternal(url);
    return { action: "deny" };
  });
  win.webContents.on("will-navigate", (event, url) => {
    const current = new URL(win.webContents.getURL());
    const next = new URL(url);
    if (next.origin !== current.origin || next.pathname !== current.pathname) event.preventDefault();
  });

  const devUrl = process.env.ELECTRON_RENDERER_URL;
  if (!app.isPackaged && devUrl) void win.loadURL(devUrl);
  else void win.loadFile(join(__dirname, "../renderer/index.html"));
  return win;
}

const isTrustedSender = (event: IpcMainInvokeEvent): boolean =>
  BrowserWindow.fromWebContents(event.sender) !== null &&
  event.senderFrame === event.sender.mainFrame;

app.on("second-instance", () => {
  const [win] = BrowserWindow.getAllWindows();
  if (win) {
    if (win.isMinimized()) win.restore();
    win.focus();
  }
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") app.quit();
});

void app.whenReady().then(() => {
  loadDevEnv();
  const dir = dataDir(smokeDir ? join(smokeDir, "data") : null);
  registerIpc(
    createHandlers({
      appInfo: () => ({
        version: app.getVersion(),
        platform: process.platform,
        dataDir: dir,
        isPackaged: app.isPackaged,
      }),
    }),
    isTrustedSender,
  );

  const win = createWindow();
  if (smokeDir) {
    void runSmoke(win, smokeDir).then(
      (code) => app.exit(code),
      (err) => {
        console.error("[smoke] crashed:", err);
        app.exit(1);
      },
    );
  }

  app.on("activate", () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

import {
  IPC_EVENTS,
  IPC_INVOKE_CHANNELS,
  type IpcResult,
  type ReqflowBridge,
} from "@reqflow/core/ipc";
import type { WorkflowRun } from "@reqflow/core";
import { contextBridge, ipcRenderer } from "electron";

// The renderer gets exactly this — no Node, no raw ipcRenderer. Keep it minimal; the typed client
// lives in the renderer (src/renderer/src/lib/api.ts).
const bridge: ReqflowBridge = {
  invoke(channel, ...args) {
    if (!IPC_INVOKE_CHANNELS.has(channel)) {
      return Promise.reject(new Error(`Blocked IPC channel "${channel}"`));
    }
    return ipcRenderer.invoke(channel, ...args) as Promise<IpcResult<unknown>>;
  },
  onRunUpdate(listener) {
    const handler = (_event: unknown, run: WorkflowRun) => listener(run);
    ipcRenderer.on(IPC_EVENTS.runUpdate, handler);
    return () => ipcRenderer.removeListener(IPC_EVENTS.runUpdate, handler);
  },
};

contextBridge.exposeInMainWorld("reqflowBridge", bridge);

